/// Case-insensitive name -> index, mirroring `ScriptGameInterfaceBase::find_func`
/// (`0x009d5360`), which resolves names by a case-insensitive linear scan at
/// *compile* time. Overloaded names resolve to the FIRST registration; the
/// real compiler then picks an overload by arity/types via `check_overload`.
pub fn find_builtin(name: &str) -> Option<&'static BuiltinDecl> {
    BUILTINS.iter().find(|b| b.name.eq_ignore_ascii_case(name))
}

/// All registrations sharing a name, in registration order (overload chain).
pub fn overloads(name: &str) -> impl Iterator<Item = &'static BuiltinDecl> + use<'_> {
    BUILTINS
        .iter()
        .filter(move |b| b.name.eq_ignore_ascii_case(name))
}

pub fn builtin(index: u32) -> Option<&'static BuiltinDecl> {
    BUILTINS.get(index as usize)
}
